do $$declare v_missing text;begin if current_setting('server_version_num')::integer<150000 then raise exception 'PostgreSQL 15+ required';end if;select string_agg(name,', 'order by name)into v_missing from unnest(array['tenants','erp_permissions','erp_tenant_memberships','erp_capability_catalog','erp_tenant_capabilities'])required(name)where to_regclass(format('public.%I',required.name))is null;if v_missing is not null then raise exception 'M16_G3_REQUIRED_OBJECTS_MISSING: %',v_missing;end if;if to_regprocedure('erp_security.has_permission(uuid,text)')is null or to_regprocedure('erp_security.is_tenant_member(uuid)')is null then raise exception 'M16_G3_SECURITY_FUNCTION_MISSING';end if;if to_regclass('supabase_migrations.schema_migrations')is null or not exists(select 1 from supabase_migrations.schema_migrations where version='0031')then raise exception 'M16_G3_REQUIRED_MIGRATION_0031_MISSING';end if;if to_regclass('public.erp_tenant_capability_exceptions')is not null or to_regprocedure('public.erp_resolve_tenant_capabilities(uuid,timestamptz)')is not null then raise exception 'M16_G3_OBJECT_COLLISION';end if;if exists(select 1 from public.tenants where slug like'm16-g3-synthetic-%')then raise exception 'M16_G3_STALE_FIXTURES_FOUND';end if;end$$;
select now()checked_at,'M16_G3_PREFLIGHT_OK'result;
